const particles = [];
const orbitCenters = [];
const numOrbits = 7;
const starDensity = 12;

function initScene() {
  for (let i = 0; i < numOrbits; i++) {
    const radius = 40 + i * 35;
    const speed = 0.0015 - i * 0.00015;
    const angleOffset = Math.random() * Math.PI * 2;

    for (let j = 0; j < starDensity; j++) {
      const angle = (j / starDensity) * Math.PI * 2 + angleOffset;
      particles.push({
        orbitRadius: radius,
        orbitSpeed: speed,
        angle: angle,
        phase: Math.random() * Math.PI * 2,
        brightness: 0.4 + Math.random() * 0.6,
        trail: []
      });
    }
  }
}

function draw(time) {
  const centerX = W() / 2;
  const centerY = H() / 2;
  const baseTime = time * 0.0005;

  ctx.fillStyle = 'rgba(255, 255, 255, 0.02)';
  ctx.fillRect(0, 0, W(), H());

  // Draw centre glow
  const centerGradient = ctx.createRadialGradient(centerX, centerY, 0, centerX, centerY, 120);
  centerGradient.addColorStop(0, 'rgba(212, 165, 165, 0.3)');
  centerGradient.addColorStop(1, 'rgba(212, 165, 165, 0)');
  ctx.fillStyle = centerGradient;
  ctx.fillRect(centerX - 120, centerY - 120, 240, 240);

  // Draw orbits
  ctx.strokeStyle = 'rgba(212, 165, 165, 0.1)';
  ctx.lineWidth = 1;
  for (let i = 0; i < numOrbits; i++) {
    const r = 40 + i * 35;
    ctx.beginPath();
    ctx.arc(centerX, centerY, r, 0, Math.PI * 2);
    ctx.stroke();
  }

  // Animate particles
  particles.forEach((p, idx) => {
    const currentAngle = p.angle + baseTime / p.orbitSpeed;
    const x = centerX + Math.cos(currentAngle) * p.orbitRadius;
    const y = centerY + Math.sin(currentAngle) * p.orbitRadius;

    // Trail
    p.trail.push({x, y});
    if (p.trail.length > 20) p.trail.shift();

    // Brightness pulse
    const pulse = 0.5 + 0.5 * Math.sin(baseTime * 2 + p.phase);
    const finalBrightness = p.brightness * pulse;

    // Draw trail
    ctx.strokeStyle = `rgba(240, 230, 210, ${finalBrightness * 0.3})`;
    ctx.lineWidth = 2 - (idx % 3) * 0.5;
    ctx.beginPath();
    if (p.trail.length > 1) {
      ctx.moveTo(p.trail[0].x, p.trail[0].y);
      for (let i = 1; i < p.trail.length; i++) {
        ctx.lineTo(p.trail[i].x, p.trail[i].y);
      }
    }
    ctx.stroke();

    // Draw star
    ctx.fillStyle = `rgba(240, 230, 210, ${finalBrightness})`;
    ctx.shadowColor = `rgba(212, 165, 165, ${finalBrightness * 0.6})`;
    ctx.shadowBlur = 8;
    ctx.beginPath();
    ctx.arc(x, y, 2.5, 0, Math.PI * 2);
    ctx.fill();
    ctx.shadowBlur = 0;
  });

  requestAnimationFrame(draw);
}

initScene();
requestAnimationFrame(draw);
